		c, o, e := runCapture(t, args...)
		return res{c, o, e}
	}

	// Missing --dir is a usage error.
	if r := call("circuit-create", "--name", "c", "--version", "1"); r.code != 2 {
		t.Fatalf("missing dir: code=%d err=%s", r.code, r.err)
	}

