const cliCorruptDef = `{"modulus":"7","constraints":[
	{"a":[{"wire":1,"coeff":"1"}],"b":[{"wire":2,"coeff":"1"}],"c":[{"wire":0,"coeff":"6"}]}]}`

type cliResult struct {
	code int
	out  string
	err  string
}

func callCLI(t *testing.T, args ...string) cliResult {
	t.Helper()
